use crate::*;
fn scan(root:&Path,dir:&Path,out:&mut Vec<Value>,total:&mut u64,truncated:&mut bool,workspace:&str,visited:&mut usize)->Result<()>{
 for entry in fs::read_dir(dir)?{let entry=entry?;*visited+=1;if *visited>50000{*truncated=true;break}let name=entry.file_name().to_string_lossy().into_owned();if name.starts_with(".lexly-")||name.starts_with(".markflow-")||matches!(name.as_str(),".git"|".obsidian"|".idea"|".vscode"|"node_modules"|"target"|"dist"){continue}let kind=entry.file_type()?;if kind.is_symlink(){continue}if out.len()>=10000||*total>32*1024*1024{*truncated=true;break}let path=entry.path();let Ok(path)=files::resolve(root,&relative(root,&path),true)else{continue};if kind.is_dir(){scan(root,&path,out,total,truncated,workspace,visited)?}else if path.extension().is_some_and(|e|e.to_string_lossy().eq_ignore_ascii_case("md")){let size=entry.metadata()?.len();if size>2*1024*1024{*truncated=true;continue}if let Ok(file)=files::read_text(&path){*total+=size;out.push(json!({"workspaceId":workspace,"path":relative(root,&path),"text":file.text,"hash":file.hash,"createdAt":entry.metadata()?.created().ok().and_then(|t|t.duration_since(UNIX_EPOCH).ok()).map(|t|t.as_millis() as u64),"modifiedAt":entry.metadata()?.modified().ok().and_then(|t|t.duration_since(UNIX_EPOCH).ok()).map(|t|t.as_millis() as u64).unwrap_or(0)}))}}}Ok(())
}
#[tauri::command] pub async fn knowledge_index(state:State<'_,AppState>)->Result<Value>{let roots={let core=state.core.lock().unwrap();core.workspaces.iter().filter_map(|w|root(&core,&w.id).ok().map(|r|(w.id.clone(),r))).collect::<Vec<_>>()};tauri::async_runtime::spawn_blocking(move||{let mut docs=vec![];let mut total=0;let mut truncated=false;let mut errors=vec![];let mut visited=0;for(id,r)in roots{if let Err(e)=scan(&r,&r,&mut docs,&mut total,&mut truncated,&id,&mut visited){errors.push(json!({"workspaceId":id,"error":e}))}}Ok(json!({"documents":docs,"truncated":truncated,"errors":errors}))}).await.map_err(|_|error("INDEX","文档索引失败"))?}

pub fn paths(root:&Path)->Result<Vec<PathBuf>>{let mut docs=vec![];let mut total=0;let mut truncated=false;scan(root,root,&mut docs,&mut total,&mut truncated,"rename",&mut 0)?;if truncated{return Err(error("LARGE","工作区超出链接更新上限，重命名尚未执行"))}Ok(docs.iter().filter_map(|d|d["path"].as_str().map(|p|root.join(p))).collect())}
